TITLE = "How powerful is the light of unity?"
INTRO = "The following messages were initially circulated in a letter from the National Spiritual Assembly of the Bahá'ís of the United States, dated Juneteenth, 2020. Echoes from Bahá'í literature have been added."
CLOSE_URL = "https://link.bahai.us/juneteenth"
CLOSE_TEXT = "The original letter used to compile this presentation can be read in full at link.bahai.us/juneteenth"

