def items():
    out = []
    n = 0
    for si, (name, dark, light, its) in enumerate(SECTIONS):
        for it in its:
            n += 1
            out.append(dict(n=n, section=name, si=si, dark=dark, light=light,
                            letter=it[0], echo=it[1], source=it[2], year=it[3]))
    return out
